func kindName(m image.Image) string {
	switch m.(type) {
	case *image.Gray:
		return "Gray"
	case *image.Gray16:
		return "Gray16"
	case *image.NRGBA:
		return "NRGBA"
	case *image.NRGBA64:
		return "NRGBA64"
	case *image.RGBA:
		return "RGBA"
	case *image.RGBA64:
		return "RGBA64"
	case *image.Paletted:
		return "Paletted"
	}
	return "?"
}

func modelName(m color.Model) string {
	switch m {
	case color.GrayModel:
		return "Gray"
	case color.Gray16Model:
		return "Gray16"
	case color.NRGBAModel:
		return "NRGBA"
	case color.NRGBA64Model:
		return "NRGBA64"
	case color.RGBAModel:
		return "RGBA"
	case color.RGBA64Model:
		return "RGBA64"
	}
	if _, ok := m.(color.Palette); ok {
		return "Paletted"
	}
	return "?"
}

func palHex(p color.Palette) string {
	var b []byte
	for _, c := range p {
		n := color.NRGBAModel.Convert(c).(color.NRGBA)
		b = append(b, n.R, n.G, n.B, n.A)
	}
	return hex.EncodeToString(b)
}

func pixOf(m image.Image) ([]byte, int) {
	switch t := m.(type) {
	case *image.Gray:
		return t.Pix, t.Stride
	case *image.Gray16:
		return t.Pix, t.Stride
	case *image.NRGBA:
		return t.Pix, t.Stride
	case *image.NRGBA64:
		return t.Pix, t.Stride
	case *image.RGBA:
		return t.Pix, t.Stride
	case *image.RGBA64:
		return t.Pix, t.Stride
	case *image.Paletted:
		return t.Pix, t.Stride
	}
	return nil, 0
}

func describe(m image.Image) string {
	pix, stride := pixOf(m)
	b := m.Bounds()
	s := fmt.Sprintf("%s %dx%d stride=%d", kindName(m), b.Dx(), b.Dy(), stride)
	if p, ok := m.(*image.Paletted); ok {
		s += fmt.Sprintf(" pal%d=%s", len(p.Palette), palHex(p.Palette))
	}
	r, g, bb, a := m.At(b.Dx()-1, b.Dy()-1).RGBA()
	s += fmt.Sprintf(" last=(%d, %d, %d, %d)", r, g, bb, a)
	r, g, bb, a = m.At(0, 0).RGBA()
	s += fmt.Sprintf(" first=(%d, %d, %d, %d)", r, g, bb, a)
	if len(pix) <= 300 {
		s += " pix=" + hex.EncodeToString(pix)
	} else {
		s += fmt.Sprintf(" pixlen=%d pixcrc=%d", len(pix), crc32.ChecksumIEEE(pix))
	}
	return s
}

func decodeOne(name string, data []byte) {
	m, err := png.Decode(bytes.NewReader(data))
	if err != nil {
		fmt.Println(name, "err", err.Error())
	} else {
		fmt.Println(name, describe(m))
	}
	c, err := png.DecodeConfig(bytes.NewReader(data))
	if err != nil {
		fmt.Println("  cfg err", err.Error())
	} else {
		s := fmt.Sprintf("  cfg %s %dx%d", modelName(c.ColorModel), c.Width, c.Height)
		if p, ok := c.ColorModel.(color.Palette); ok {
			s += " pal=" + palHex(p)
		}
		fmt.Println(s)
	}
}

func f8(i int) byte { return byte((i*73 + 41) % 256) }

var alphas8 = []byte{0, 255, 128, 7, 200, 64}
var alphas16 = []uint16{0x0000, 0xffff, 0x8000, 0x0102, 0xfff0, 0x00ff}

func fill(pix []byte, bpp int, alpha int) {
	// alpha: 0 none, 1 opaque, 2 translucent
	for i := range pix {
		pix[i] = f8(i)
	}
	if alpha == 0 {
		return
	}
	for p := 0; p*bpp < len(pix); p++ {
		if bpp == 4 {
			if alpha == 1 {
				pix[p*4+3] = 0xff
			} else {
				pix[p*4+3] = alphas8[p%6]
			}
		} else {
			v := uint16(0xffff)
			if alpha == 2 {
				v = alphas16[p%6]
			}
			pix[p*8+6] = byte(v >> 8)
			pix[p*8+7] = byte(v)
		}
	}
}

func makePal(n int, trans bool) color.Palette {
	p := make(color.Palette, n)
	for i := range p {
		a := byte(0xff)
		if trans && i%3 == 1 {
			a = byte(i * 17)
		}
		p[i] = color.NRGBA{f8(3 * i), f8(3*i + 1), f8(3*i + 2), a}
	}
	return p
}

func makeImg(kind string, w, h, alpha, npal int, trans bool) image.Image {
	r := image.Rect(0, 0, w, h)
	switch kind {
	case "Gray":
		m := image.NewGray(r)
		fill(m.Pix, 1, 0)
		return m
	case "Gray16":
		m := image.NewGray16(r)
		fill(m.Pix, 2, 0)
		return m
	case "RGBA":
		m := image.NewRGBA(r)
		fill(m.Pix, 4, alpha)
		return m
	case "NRGBA":
		m := image.NewNRGBA(r)
		fill(m.Pix, 4, alpha)
		return m
	case "RGBA64":
		m := image.NewRGBA64(r)
		fill(m.Pix, 8, alpha)
		return m
	case "NRGBA64":
		m := image.NewNRGBA64(r)
		fill(m.Pix, 8, alpha)
		return m
	}
	m := image.NewPaletted(r, makePal(npal, trans))
	for i := range m.Pix {
		if npal > 0 {
			m.Pix[i] = byte((i*7 + 3) % npal)
		}
	}
	return m
}

func idatPayload(data []byte) ([]byte, int) {
	var out []byte
	n := 0
	p := 8
	for p+8 <= len(data) {
		l := int(binary.BigEndian.Uint32(data[p:]))
		if string(data[p+4:p+8]) == "IDAT" {
			out = append(out, data[p+8:p+8+l]...)
			n++
		}
		p += 12 + l
	}
	return out, n
}

func main() {
	fmt.Println("== decode")
	for _, v := range vectors {
		b, _ := hex.DecodeString(v.hex)
		decodeOne(v.name, b)
	}

	fmt.Println("== encode")
	type ec struct {
		kind              string
		w, h, alpha, npal int
		trans             bool
	}
	cases := []ec{
		{"Gray", 5, 3, 0, 0, false},
		{"Gray16", 4, 3, 0, 0, false},
		{"RGBA", 4, 3, 1, 0, false},
		{"RGBA", 6, 3, 2, 0, false},
		{"NRGBA", 3, 3, 1, 0, false},
		{"NRGBA", 5, 2, 2, 0, false},
		{"RGBA64", 3, 2, 1, 0, false},
		{"RGBA64", 3, 4, 2, 0, false},
		{"NRGBA64", 2, 3, 1, 0, false},
		{"NRGBA64", 4, 3, 2, 0, false},
		{"Paletted", 11, 3, 0, 1, false},
		{"Paletted", 11, 3, 0, 2, false},
		{"Paletted", 5, 3, 0, 3, true},
		{"Paletted", 7, 2, 0, 16, false},
		{"Paletted", 5, 5, 0, 17, true},
		{"Paletted", 6, 4, 0, 256, false},
		{"Gray", 16, 16, 0, 0, false},
		{"NRGBA", 16, 16, 2, 0, false},
		{"RGBA64", 16, 9, 2, 0, false},
	}
	levels := []png.CompressionLevel{png.NoCompression, png.DefaultCompression, png.BestSpeed, png.BestCompression}
	for ci, c := range cases {
		m := makeImg(c.kind, c.w, c.h, c.alpha, c.npal, c.trans)
		lvs := levels[:2]
		if ci == 3 || ci == 9 || ci == 17 {
			lvs = levels
		}
		for _, lv := range lvs {
			var buf bytes.Buffer
			err := (&png.Encoder{CompressionLevel: lv}).Encode(&buf, m)
			if err != nil {
				fmt.Println(ci, lv, "err", err.Error())
				continue
			}
			out := buf.Bytes()
			payload, nidat := idatPayload(out)
			zr, _ := zlib.NewReader(bytes.NewReader(payload))
			raw, _ := io.ReadAll(zr)
			if lv == png.NoCompression {
				if len(out) <= 400 {
					fmt.Println(ci, lv, "png", hex.EncodeToString(out))
				}
				fmt.Println(ci, lv, "len", len(out), "crc", crc32.ChecksumIEEE(out), "idats", nidat)
			}
			fmt.Println(ci, lv, "raw", len(raw), crc32.ChecksumIEEE(raw), "head", hex.EncodeToString(raw[:min(len(raw), 40)]))
			d, err := png.Decode(bytes.NewReader(out))
			if err != nil {
				fmt.Println(ci, lv, "decode err", err.Error())
			} else {
				fmt.Println(ci, lv, "decoded", describe(d))
			}
		}
	}
	// a larger image: several stored blocks and bufio-split IDAT chunks
	big := image.NewGray(image.Rect(0, 0, 300, 240))
	fill(big.Pix, 1, 0)
	var buf bytes.Buffer
	(&png.Encoder{CompressionLevel: png.NoCompression}).Encode(&buf, big)
	out := buf.Bytes()
	_, nidat := idatPayload(out)
	fmt.Println("big len", len(out), "crc", crc32.ChecksumIEEE(out), "idats", nidat)
	d, err := png.Decode(bytes.NewReader(out))
	if err != nil {
		fmt.Println("big decode err", err)
	} else {
		fmt.Println("big decoded", describe(d))
	}

	fmt.Println("== encode errors")
	for _, m := range []image.Image{
		image.NewGray(image.Rect(0, 0, 0, 0)),
		image.NewRGBA(image.Rect(0, 0, 3, 0)),
		image.NewPaletted(image.Rect(0, 0, 2, 2), color.Palette{}),
		makeImg("Paletted", 2, 2, 0, 257, false),
	} {
		var buf bytes.Buffer
		err := png.Encode(&buf, m)
		fmt.Println("err", err)
	}
}
